import json,numpy as np
from scipy.spatial.transform import Rotation
from scipy.spatial import cKDTree

def cloud(meta,c,im,dep):
 K=np.array(meta['cameras'][c]['intrinsic_cv']); T=np.array(meta['cameras'][c]['cam2world_gl'])
 v,u=np.indices(dep.shape); d=dep.astype(float)
 p=np.stack(((u-K[0,2])/K[0,0]*d,-(v-K[1,2])/K[1,1]*d,-d),-1)
 return p@T[:3,:3].T+T[:3,3]

def handcloud(meta,ims,deps):
 pp=[]
 for c in ims:
  p=cloud(meta,c,ims[c],deps[c]); col=ims[c].astype(float)
  mask=(col.min(-1)>115)&(col.max(-1)-col.min(-1)<38)&(p[...,2]>.60)&(p[...,2]<.94)&(p[...,0]>-.25)&(p[...,0]<.3)&(p[...,1]>-.12)&(p[...,1]<.37)
  pp.append(p[mask])
 return np.concatenate(pp)

def icp(a,b):
 # a to b
 tree=cKDTree(b); R=np.eye(3); t=np.zeros(3)
 for it in range(60):
  aa=a@R.T+t; dist,idx=tree.query(aa); good=dist<.025
  if sum(good)<50: raise ValueError('ICP too few')
  # trim
  good &= dist<np.quantile(dist[good],.8)
  x=aa[good]; y=b[idx[good]]; xm=x.mean(0); ym=y.mean(0)
  U,s,Vt=np.linalg.svd((x-xm).T@(y-ym)); RR=Vt.T@U.T
  if np.linalg.det(RR)<0: Vt[-1]*=-1; RR=Vt.T@U.T
  tt=ym-RR@xm; R=RR@R; t=RR@t+tt
  if np.linalg.norm(tt)<1e-7 and np.linalg.norm(RR-np.eye(3))<1e-6: break
 return R,t,float(np.mean(dist[good])),int(sum(good))

if __name__=='__main__':
 from PIL import Image
 m=json.load(open('/app/runs/latest/meta.json')); ims={c:np.load('/app/output/'+c+'_rgb.npy') for c in m['cameras']}; deps={c:np.load('/app/runs/latest/depth_'+c+'.npy') for c in m['cameras']}
 p=handcloud(m,ims,deps); print('hand',len(p),p.min(0),p.max(0),p.mean(0)); np.save('/app/output/hand0.npy',p)
 for c in ims:
  p=cloud(m,c,ims[c],deps[c]);
  print(c,'center',p[120,160]);
  for uv in ([(147,134),(171,129),(188,129),(154,130)] if c=='front' else []): print(uv,p[uv[1],uv[0]])
PY
