cat > /app/output/kin.py <<'PY'
import numpy as np,json
from scipy.spatial.transform import Rotation as Rot
from scipy.optimize import least_squares
q0=np.array(json.load(open('/app/runs/initial/meta.json'))['proprio']['now'][:7])

def rz(q): return Rot.from_rotvec([0,0,q]).as_matrix()
def ry(q): return Rot.from_rotvec([0,q,0]).as_matrix()
base=np.array([0.,-.55,.0])
def fk(q,full=False):
 R=np.eye(3); p=base.copy(); axes=[]; centers=[]
 for j in range(7):
  if j==0: p+=R@np.array([0,0,.36])
  if j==2: p+=R@np.array([0,0,.42])
  if j==4: p+=R@np.array([0,0,.4])
  if j==6: p+=R@np.array([0,0,.126])
  axis= np.array([0,0,1]) if j%2==0 else np.array([0,(-1 if j in (1,5) else 1),0])
  axes.append(R@axis); centers.append(p.copy()); R=R@Rot.from_rotvec(axis*q[j]).as_matrix()
 return (p,R,np.array(axes),np.array(centers)) if full else (p,R)
def ik(pdes,Rdes,qstart):
 def fun(q):
  p,R=fk(q); return np.r_[10*(p-pdes),Rot.from_matrix(Rdes@R.T).as_rotvec(),.01*(q-qstart)]
 lim=json.load(open('/app/output/spec.json'))['action_types']['joint_position']; out=least_squares(fun,qstart,bounds=(lim['lower'][:7],lim['upper'][:7]),max_nfev=250)
 return out.x,np.linalg.norm(fun(out.x)[:6])
if __name__=='__main__':
 p,R,axs,cs=fk(q0,True); print(p,R,axs,cs)
